'use strict'

const i18n 			= require( './i18n.min' )

// Polyfill: make electron-store work in renderer
try {
	const electron = require( 'electron' )
	const remote = require( '@electron/remote' )
	if( !electron.app ) {
		electron.app = remote.app
	}
} catch( e ) {}

const {ipcRenderer} = require( 'electron' )

const Store 		= require( 'electron-store' )

let store
try {
	store = new Store()
} catch( e ) {
	// Don't crash, let the form show even if store fails
	store = { get: () => null, set: () => {} }
}

const Mousetrap 	= require( 'mousetrap' )

const $ 			= require( 'jquery' )
const jqueryI18next = require( 'jquery-i18next' )

jqueryI18next.init(i18n, $)


//note(dgmid): log exceptions

window.onerror = function( error, url, line ) {
	
	ipcRenderer.send( 'error-in-render', {error, url, line} )
}



//note(dgmid): set lang & localize strings

$('html').attr('lang', i18n.language)
$('header').localize()
$('label').localize()
$('input').localize()
$('button').localize()


//note(dgmid): get login credentials

const 	server 		= store.get( 'loginCredentials.server' ),
		username 	= store.get( 'loginCredentials.username' ),
		password 	= store.get( 'loginCredentials.password' )

if( server ) { $('input[name="server"]').val( server ) }



//note(dgmid): register kbd shortcut
Mousetrap.bind('command+.', function() {
	
	closeModal()
})



//note(dgmid): close modal

function closeModal() {
	
	ipcRenderer.send( 'close-current-window' )
}



$(document).ready(function() {	
	
	//note(dgmid): Login always enabled so user can re-authenticate
	
	if( username && password && server ) {
		
		$('#logout').prop('disabled', false)
		
	} else if( server ) {
		
		$('#logout').prop('disabled', true)
		
	} else {
		
		$('#logout').prop('disabled', true)
	}
	
	$('#update').prop('disabled', false)
	
	//note(dgmid): cancel modal
	
	$('#cancel').click( function() {
		
		closeModal()
	})
	
	
	//note(dgmid): update data
	
	$('#modal-form').submit( function( e ) {
		
		e.preventDefault()
		
		let theserver = $('input[name="server"]').val()
		
		// Auto-convert http:// to https:// and add https:// if missing protocol
		if( theserver && theserver.length > 0 ) {
			
			if( theserver.startsWith('http://') ) {
				
				theserver = 'https://' + theserver.slice(7)
				
			} else if( !theserver.startsWith('https://') && !theserver.startsWith('http://') ) {
				
				theserver = 'https://' + theserver
			}
			
			// Strip trailing slash to avoid double slash in login flow URL
			if( theserver.endsWith('/') ) {
				theserver = theserver.slice(0, -1)
			}
		}
		
		store.set( 'loginCredentials.server', theserver )
		
		ipcRenderer.send( 'loginflow', theserver )
	})
	
	
	//note(dgmid): logout
	
	$('#logout').click( function() {
		
		store.set( 'loginCredentials', {
			
			server: '',
			username: '',
			password: ''
		} )
		
		ipcRenderer.send('refresh', 'refresh')
		
		closeModal()
	})
	
	
	//note(dgmid): continue offline — tell the main window to load the local mirror
	//in read-only mode (no credentials needed). main.js closes this window.
	
	$('#offline').click( function() {
		
		ipcRenderer.send( 'continue-offline' )
	})
})
